INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','easy','flashcard','What temperature (oral) defines fever in adults?','["38.3 °C (101 °F); some use 38.0 °C as the threshold"]','A','Rectal temperature is the gold standard; axillary readings are ~0.5 °C lower. In neutropenic patients any temperature 38.0 °C is significant.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','easy','flashcard','Define Fever of Unknown Origin (FUO).','["Fever 38.3 °C on 3+ occasions, lasting > 3 weeks, with no diagnosis after 3 outpatient visits or 3 days in hospital (Durack & Street criteria)"]','A','Classic Durack & Street criteria (1991). Causes: infection (most common), malignancy, autoimmune, miscellaneous. Ghana STG refers undiagnosed fever > 10 days to specialist as PUO.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','easy','flashcard','List the minimum investigations for a febrile patient in Ghana.','["FBC, blood film for malaria parasites, Rapid Diagnostic Test (RDT) for malaria; cultures of blood/urine/sputum as clinically indicated"]','A','Ghana STG 2017 mandates RDT or thick/thin blood film for every febrile patient. If malaria is excluded, broaden workup: urine C&S, CXR, blood cultures.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','medium','flashcard','Describe the cytokine pathway that generates fever.','["Exogenous pyrogens activate macrophages to release IL-1, IL-6, TNF-alpha, which stimulate hypothalamic PGE2 production, raising the thermoregulatory set-point"]','A','Antipyretics (paracetamol, NSAIDs) block COX enzymes, reducing PGE2 synthesis. Aspirin is CONTRAINDICATED in children < 16 years (Reye syndrome risk).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','medium','flashcard','State the qSOFA criteria for bedside sepsis screening.','["Respiratory rate >= 22/min; altered mental status (GCS < 15); systolic BP <= 100 mmHg — 2 or more predicts poor outcome"]','A','qSOFA requires no lab tests. Full SOFA used in ICU. Sepsis-3 definition: life-threatening organ dysfunction (SOFA >= 2) caused by dysregulated host response to infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','medium','flashcard','What is the Hour-1 Sepsis Bundle for septic shock?','["Measure lactate; obtain blood cultures; give broad-spectrum antibiotics; 30 mL/kg IV crystalloid for hypotension/lactate >= 4 mmol/L; start vasopressors if MAP < 65 mmHg"]','A','Surviving Sepsis Campaign 2018. Norepinephrine is first-line vasopressor. Target MAP >= 65 mmHg and urine output >= 0.5 mL/kg/h. Hydrocortisone added for refractory septic shock.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','medium','flashcard','What empiric antibiotic regimen does Ghana STG recommend for community-acquired sepsis in adults?','["Ampicillin IV + Gentamicin IV +/- Metronidazole IV; or Amoxicillin-Clavulanate IV + Metronidazole depending on suspected source"]','A','Ghana STG 2017 advises de-escalation once cultures available. Ceftriaxone IV 2 g daily is an alternative. Always obtain cultures before first antibiotic dose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','medium','flashcard','Name 5 non-infectious causes of FUO.','["Lymphoma, SLE, adult-onset Still''s disease, temporal arteritis, drug fever (drug-induced hypersensitivity)"]','A','Mnemonic MIND: Malignancy, Inflammation/autoimmune, Non-infectious granulomatous (sarcoidosis), Drug fever. TB is infectious but often overlooked in sub-Saharan Africa as a non-infectious mimic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','hard','flashcard','Distinguish SIRS, sepsis, and septic shock using Sepsis-3 definitions.','["SIRS: >= 2 systemic inflammatory criteria (now largely abandoned). Sepsis: infection + acute organ dysfunction (SOFA >= 2). Septic shock: sepsis + vasopressors needed to maintain MAP >= 65 + lactate > 2 mmol/L despite adequate fluids"]','A','Sepsis-3 (Singer et al., JAMA 2016) removed severe sepsis. Lactate > 4 mmol/L with hypotension marks refractory shock with > 40% mortality. SOFA includes renal, hepatic, respiratory, coagulation, cardiovascular, neurological.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','hard','flashcard','A 35-year-old returns from rural Ghana with 5 days of fever, rigors, and jaundice. RDT is negative. What is your approach?','["Repeat thick blood film x3 on consecutive days; consider typhoid (blood culture/Widal), viral haemorrhagic fever (isolate patient), leptospirosis, relapsing fever, rickettsial disease"]','A','Single negative RDT does not exclude malaria — sensitivity drops in low-parasitaemia P. falciparum. VHF must be excluded before removing isolation. Weil-Felix/Leptospira serology if travel/water exposure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','easy','flashcard','Which Plasmodium species causes the most severe malaria, and which vector transmits it?','["Plasmodium falciparum causes the most severe disease; transmitted by the female Anopheles mosquito"]','A','P. vivax/ovale form liver hypnozoites causing relapse (treat with primaquine). P. malariae causes quartan fever every 72 h. P. falciparum is the predominant species in Ghana and sub-Saharan Africa.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','easy','flashcard','What are the first-line treatments for uncomplicated malaria per Ghana STG 2017?','["Artesunate + Amodiaquine (AS+AQ) once daily x 3 days; OR Artemether + Lumefantrine (AL) x 3 days; OR Dihydroartemisinin + Piperaquine x 3 days — all are ACTs"]','A','All three are artemisinin-based combination therapies (ACTs). Ghana STG lists AS+AQ as the first ACT option. AL must be taken with food to enhance lumefantrine absorption (fatty meal doubles bioavailability).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','easy','flashcard','How is severe malaria treated per Ghana STG 2017?','["IV/IM Artesunate 2.4 mg/kg at 0, 12, 24 h then once daily until oral tolerated; follow with full 3-day oral ACT course; children < 20 kg receive 3 mg/kg"]','A','Ghana STG: parenteral treatment for minimum 24 h regardless of clinical improvement. Pre-referral: IM Artesunate or rectal Artesunate suppository (children < 6 years). Alternative: IV Quinine 10 mg/kg over 4-8 h 8-hourly + Clindamycin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','medium','flashcard','List 6 WHO criteria for severe/complicated malaria.','["Impaired consciousness (cerebral malaria), severe anaemia (Hb < 7 g/dL), respiratory distress/pulmonary oedema, hypoglycaemia (< 2.2 mmol/L), acute kidney injury, hyperparasitaemia (> 5% RBCs infected)"]','A','Also: haemoglobinuria (blackwater fever), circulatory collapse, abnormal bleeding, repeated convulsions, jaundice + organ dysfunction. ANY single criterion = severe malaria requiring parenteral therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','medium','flashcard','What is the preferred diagnostic test for malaria and what are alternatives?','["Thick and thin blood films (gold standard) — identifies species and quantifies parasitaemia; alternatives: Rapid Diagnostic Test (RDT) detects HRP-2 antigen; PCR for low-density infections"]','A','RDT sensitivity ~95% for P. falciparum. Thick film concentrates parasites 20x. Thin film allows species identification and parasite count per microlitre. Ghana STG mandates one of these before treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','medium','flashcard','Which antimalarial is safe in first-trimester pregnancy for uncomplicated malaria?','["Quinine oral + Clindamycin for 7 days — ACTs are avoided in first trimester due to limited embryo-safety data; ACTs acceptable in 2nd/3rd trimester"]','A','Ghana STG: for severe malaria in ANY trimester, IV Artesunate is given (benefit outweighs risk). IPTp with Sulfadoxine-Pyrimethamine (SP) at each ANC visit after quickening prevents placental malaria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','medium','flashcard','What is the mechanism of action of artemisinin compounds?','["Endoperoxide bridge reacts with haem iron (Fe2+) in the parasite food vacuole generating free radicals that alkylate parasite proteins, causing rapid schizontocidal killing"]','A','Artemisinins have the fastest parasite clearance rate of all antimalarials. Resistance emerging in Southeast Asia (kelch13 mutations). Short half-life necessitates combination with a longer-acting partner drug.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','medium','flashcard','What is Intermittent Preventive Treatment in Pregnancy (IPTp) in Ghana?','["Sulfadoxine-Pyrimethamine (SP/Fansidar) given at each ANC visit after quickening (>= 2 doses, at least 1 month apart) under directly observed therapy — reduces low birth weight and maternal anaemia"]','A','SP is contraindicated in 1st trimester and in HIV-positive women on co-trimoxazole prophylaxis (both are antifolates — additive toxicity). Ghana NTP integrates IPTp into routine ANC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','hard','flashcard','A child presents with coma, Hb 4.2 g/dL, blood glucose 1.8 mmol/L, and P. falciparum on blood film. Outline immediate management.','["IV access; 10% dextrose 5 mL/kg for hypoglycaemia; packed red cell transfusion; IV Artesunate 3 mg/kg (child < 20 kg); IV Diazepam for convulsions; lumbar puncture to exclude co-existing meningitis"]','A','Cerebral malaria and meningitis can co-exist in endemic areas. Hypoglycaemia is worsened by quinine (stimulates insulin release). Monitor blood glucose every 4 hours. Dexamethasone is NOT beneficial and may worsen outcome in cerebral malaria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','hard','flashcard','What is blackwater fever and how is it managed?','["Massive intravascular haemolysis causing haemoglobinuria (cola/black urine), acute kidney injury, and severe anaemia; associated with P. falciparum, quinine use, and G6PD deficiency; manage with IV Artesunate, IV fluids, and dialysis for AKI"]','A','Discontinue quinine/primaquine if G6PD deficiency suspected. Avoid further haemolytic agents. Blood transfusion for severe anaemia. High mortality if AKI progresses to oliguria. Monitor urine output and renal function closely.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','easy','flashcard','What is the standard first-line TB regimen for new cases per Ghana STG 2017?','["2 months HRZE (Isoniazid, Rifampicin, Pyrazinamide, Ethambutol) initial phase; then 4 months HR continuation phase; total 6 months — Category I"]','A','Weight-based dosing: H 4-6 mg/kg, R 8-12 mg/kg, Z 20-30 mg/kg, E 15-20 mg/kg daily. Directly Observed Therapy (DOT) is mandatory throughout all phases per Ghana NTP.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','easy','flashcard','What does a Mantoux (TST) result >= 10 mm indicate?','["Positive TST suggesting M. tuberculosis infection (latent or active); threshold lowered to >= 5 mm in HIV-positive individuals and close TB contacts"]','A','TST cannot distinguish latent from active TB. False negatives: HIV, malnutrition, miliary TB, recent infection (< 8 weeks), corticosteroids. IGRA (QuantiFERON-TB Gold) is more specific but costlier.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','easy','flashcard','What is GeneXpert MTB/RIF and what does it detect?','["Cartridge-based real-time PCR simultaneously detecting M. tuberculosis DNA and rifampicin resistance (rpoB mutations) within 2 hours from sputum"]','A','WHO-endorsed as initial TB diagnostic. Sensitivity ~88% for smear-negative TB; specificity ~99%. Endorsed by Ghana NTP as preferred rapid diagnostic. Can be used on non-sputum samples for extrapulmonary TB.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','medium','flashcard','What regimen does Ghana STG use for previously treated TB (Category II)?','["2 months SHRZE (add Streptomycin IM in addition to HRZE) + 1 month HRZE initial phase; then 5 months HRE continuation phase; total 8 months; DST mandatory before starting"]','A','S = Streptomycin given for first 2 months only. If DST confirms MDR-TB, switch to second-line regimen. Sputum smear/culture monitored at months 2, 5, and 8 to assess treatment response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','medium','flashcard','Define MDR-TB and XDR-TB per Ghana STG 2017.','["MDR-TB: resistance to at least Isoniazid AND Rifampicin. XDR-TB: MDR-TB plus resistance to a fluoroquinolone AND at least one injectable second-line drug (kanamycin, capreomycin, or amikacin)"]','A','Ghana STG lists kanamycin, levofloxacin, ethionamide, cycloserine, PAS for MDR-TB (18-24 months treatment). Community-based care preferred over facility-based in Ghana. Treatment adherence is critical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','medium','flashcard','What CXR findings are classic for post-primary (reactivation) TB?','["Upper lobe infiltrates/consolidation, cavitation, fibrosis/scarring, calcified Ghon focus (primary TB); hilar lymphadenopathy in primary TB; miliary TB: 1-2 mm nodules throughout both lung fields"]','A','Primary TB in children: lower/middle lobe infiltrate + hilar adenopathy (classic pattern). Reactivation: apical-posterior upper lobes or superior segments of lower lobes. CXR not specific; GeneXpert/culture confirms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','medium','flashcard','What is the TB meningitis regimen per Ghana STG?','["2 months HRZE initial phase, then 10 months HR continuation phase (total 12 months); adjunctive Dexamethasone for the first month reduces mortality and neurological complications"]','A','Extended continuation phase (10 months HR vs standard 4 months). Ethambutol has poor CNS penetration — some regimens omit it in TBM. Dexamethasone 0.3-0.4 mg/kg/day tapering over 6-8 weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','medium','flashcard','When should ART be started in a TB/HIV co-infected patient?','["Within 2 weeks of TB treatment if CD4 < 50 cells/µL; within 8 weeks if CD4 >= 50 cells/µL; exception: TB meningitis — delay ART 4-8 weeks to reduce IRIS risk"]','A','Preferred ART in TB/HIV co-infection: TDF + 3TC + EFV. Efavirenz preferred over Nevirapine due to rifampicin enzyme induction reducing NVP levels. IRIS risk: 15-40% of TB/HIV patients starting ART.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','hard','flashcard','State the adverse effects of each first-line TB drug using HRZE mnemonic.','["H (Isoniazid): peripheral neuropathy, hepatotoxicity. R (Rifampicin): hepatotoxicity, orange discolouration, drug interactions (CYP inducer). Z (Pyrazinamide): hepatotoxicity, hyperuricaemia/gout. E (Ethambutol): optic neuritis (red-green colour blindness)"]','A','Pyridoxine (B6) 10-25 mg/day co-prescribed with isoniazid prevents peripheral neuropathy. Baseline LFTs before starting all drugs. Monitor visual acuity monthly on ethambutol. Rifampicin is a potent CYP3A4 inducer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','hard','flashcard','Which children should receive isoniazid preventive therapy (IPT) per Ghana STG?','["All children < 5 years and all HIV-positive children who are TB contacts; isoniazid 10 mg/kg/day for at least 6 months; exclude active TB before starting; co-administer pyridoxine"]','A','Ghana STG 2017 (page 475). IPT reduces TB incidence by ~60% in HIV-positive individuals. In HIV-positive adults without active TB: isoniazid 300 mg daily x 6 months. Extend to 36 months in high-prevalence settings.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','easy','flashcard','What is the preferred first-line ART regimen for adults in Ghana per Ghana STG 2017?','["Tenofovir (TDF) + Lamivudine (3TC) + Efavirenz (EFV) as fixed-dose combination once daily"]','A','Ghana STG Table 17-2. Alternative: TDF + 3TC + Nevirapine or Zidovudine + 3TC + Nevirapine. All HIV-positive patients are referred to an accredited ART centre in Ghana.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','easy','flashcard','At what CD4 count is ART recommended to be initiated?','["ART recommended for ALL HIV-positive individuals regardless of CD4 count — universal test and treat (WHO 2015/2016, adopted by Ghana)"]','A','Previously threshold was CD4 < 350 then < 500 cells/uL. Universal treatment reduces transmission by 96% (HPTN 052). In Ghana, all diagnosed patients are referred for immediate ART initiation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','easy','flashcard','What OI prophylaxis is given at CD4 < 200 cells/uL?','["Co-trimoxazole (TMP-SMX) 960 mg daily prevents PCP, Toxoplasma, and bacterial infections; stop when CD4 > 200 for >= 3 months on ART"]','A','CD4 < 100: add Fluconazole for cryptococcal prophylaxis where prevalent. Azithromycin 1.2 g weekly for MAC prophylaxis at CD4 < 50. Isoniazid preventive therapy at any CD4 count to prevent TB.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','medium','flashcard','Define Immune Reconstitution Inflammatory Syndrome (IRIS).','["Paradoxical worsening or unmasking of an opportunistic infection after ART initiation due to recovering immune function; typically 2-8 weeks after starting ART"]','A','Paradoxical IRIS: previously treated OI worsens. Unmasking IRIS: subclinical OI becomes clinically apparent. TB and Cryptococcus are commonest triggers. Manage with NSAIDs; steroids for severe cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','medium','flashcard','How is HIV/Hepatitis B co-infection managed per Ghana STG?','["Preferred regimen: Lamivudine + Tenofovir + Efavirenz — both 3TC and TDF are active against HBV and HIV, preventing HBV reactivation flare"]','A','Ghana STG Table 17-4. Screen all HIV patients for HBsAg. Stopping 3TC or TDF risks fatal HBV flare. Never use HBV-active drugs as HIV monotherapy. Lamivudine + Tenofovir covers both viruses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','medium','flashcard','What are the mechanisms of action of the 3 major ART drug classes?','["NRTIs: chain termination of reverse transcriptase. NNRTIs: non-competitive inhibition of reverse transcriptase. Protease inhibitors: block HIV protease preventing viral maturation"]','A','Integrase inhibitors (e.g., dolutegravir) block HIV integrase — now preferred 3rd agent globally due to high barrier to resistance. Entry inhibitors (Maraviroc) block CCR5 co-receptor.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','medium','flashcard','What is the treatment for PCP in AIDS?','["High-dose co-trimoxazole TMP 15-20 mg/kg/day for 21 days; add Prednisolone 40 mg BD if PaO2 < 70 mmHg or A-a gradient > 35 mmHg to reduce mortality"]','A','PCP typically at CD4 < 200. CXR: bilateral perihilar ground-glass infiltrates. LDH elevated (> 500 = poor prognosis). Induced sputum or BAL for GMS stain confirms. 2nd line: IV Pentamidine or Primaquine + Clindamycin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','medium','flashcard','What PEP regimen is recommended for high-risk occupational HIV exposure per Ghana STG?','["TDF 300 mg + Emtricitabine 200 mg daily + Lopinavir/ritonavir 400/100 mg 12-hourly for 28 days; initiate within 1-2 hours, no later than 72 hours post-exposure"]','A','Ghana STG Note 17-1. Low risk: 2-drug PEP. High risk: 3-drug PEP. Baseline HIV test, LFTs, FBC. HIV serology follow-up at 6 weeks, 3 months, 6 months. Document all exposure details.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','hard','flashcard','A patient on TDF develops rising creatinine and glycosuria. Diagnosis and management?','["Tenofovir-induced Fanconi syndrome (proximal renal tubular dysfunction) — switch TDF to Abacavir (if HLA-B*5701 negative) or Zidovudine; monitor renal function closely"]','A','Fanconi syndrome: reduced GFR, phosphaturia, glycosuria, aminoaciduria. Risk: low BMI, pre-existing CKD, concomitant nephrotoxins. Check urinalysis and creatinine at every visit on TDF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','hard','flashcard','Name 4 AIDS-defining illnesses with CD4 count thresholds.','["PCP (CD4 < 200), Toxoplasma encephalitis (< 100), CMV retinitis (< 50), Cryptococcal meningitis (< 100); also Kaposi sarcoma, MAC bacteraemia, CNS lymphoma at very low CD4"]','A','AIDS defined as CD4 < 200 cells/uL OR any AIDS-defining condition regardless of CD4. Cryptococcus: Amphotericin B + Flucytosine 2-week induction then Fluconazole consolidation/maintenance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','easy','flashcard','What does CURB-65 stand for and what score requires hospitalisation?','["C=Confusion, U=Urea > 7 mmol/L, R=Respiratory rate >= 30/min, B=BP systolic < 90 or diastolic <= 60 mmHg, 65=Age >= 65; score >= 2 requires hospitalisation"]','A','Ghana STG Box 8-1: score 0-1 outpatient; >= 2 hospital; >= 3 consider ICU/HDU. CRB-65 (no urea) used in primary care settings. PSI/PORT score is a more complex alternative.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','easy','flashcard','What is the first-line treatment for mild CAP (outpatient) per Ghana STG 2017?','["Amoxicillin 1 g 8-hourly oral x 7 days PLUS Azithromycin 500 mg daily x 6 days (covers atypical organisms)"]','A','Ghana STG Evidence Rating A. Azithromycin added to cover Mycoplasma, Legionella, Chlamydophila. Penicillin allergy: Erythromycin 500 mg 6-hourly x 7 days. 2nd line: Cefuroxime 500 mg 12-hourly or Doxycycline.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','easy','flashcard','Which organism is the commonest cause of community-acquired pneumonia?','["Streptococcus pneumoniae (pneumococcus) — responsible for 30-40% of CAP cases requiring hospitalisation"]','A','Other common CAP pathogens: H. influenzae, Klebsiella pneumoniae, Mycoplasma pneumoniae, Legionella pneumophila, S. aureus (especially post-influenza). Legionella clue: hyponatraemia + diarrhoea + high LDH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','medium','flashcard','What are the hallmark features of atypical pneumonia?','["Gradual onset; dry non-productive cough; minimal auscultatory findings despite CXR infiltrates; extra-pulmonary features (headache, myalgia, diarrhoea); patchy bilateral interstitial infiltrates"]','A','Causes: Mycoplasma pneumoniae (cold agglutinins positive), Chlamydophila pneumoniae, Legionella pneumophila, Coxiella burnetii (Q fever). Treated with macrolides (azithromycin) or fluoroquinolones (levofloxacin).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','medium','flashcard','What is the empiric treatment for hospitalised severe CAP per Ghana STG?','["IV Amoxicillin-Clavulanate 1.2 g 8-hourly PLUS IV Azithromycin 500 mg daily; 2nd line: IV Ceftriaxone 2 g daily PLUS Azithromycin; maintain O2 saturation > 92%"]','A','Ghana STG Evidence Rating A. Step down to oral when stable. Duration 7-10 days. Aspiration pneumonia: add IV Metronidazole 500 mg 8-hourly. Culture sputum and blood before antibiotics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','medium','flashcard','Name the organisms and treatment of hospital-acquired pneumonia (HAP).','["Gram-negative bacilli (Pseudomonas, Klebsiella, Acinetobacter), MRSA, S. aureus; treat with anti-pseudomonal beta-lactam (Piperacillin-Tazobactam or Ceftazidime) + aminoglycoside, +/- Vancomycin for MRSA"]','A','HAP develops >= 48 h after hospital admission. VAP (ventilator-associated): highest mortality (~30-50%). Tracheal aspirate culture guides de-escalation. Early-onset HAP (< 5 days) has better prognosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','medium','flashcard','What are the signs of lobar consolidation on chest examination?','["Dullness to percussion; increased vocal/tactile fremitus; bronchial breathing; whispering pectoriloquy; aegophony over the consolidated area"]','A','Contrast with pleural effusion: dullness + absent breath sounds + reduced VF. Empyema = infected effusion — stony dull, requires intercostal drainage. CXR: opacification with air bronchogram in consolidation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','medium','flashcard','What investigations should be ordered for suspected pneumonia?','["FBC, CRP, CXR, sputum Gram stain + C&S, blood cultures x2, blood urea/electrolytes, ZN stain for AFB (exclude TB), pulse oximetry, urinary pneumococcal/Legionella antigen"]','A','Blood cultures positive in only 10-15% of CAP. Urinary antigen test for Legionella (serogroup 1) and S. pneumoniae has high specificity. Serial CXR at 6 weeks to confirm radiological resolution.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','hard','flashcard','An HIV patient has progressive dyspnoea, dry cough, bilateral ground-glass infiltrates, and raised LDH. Diagnosis and treatment?','["PCP (Pneumocystis jirovecii pneumonia); treat with co-trimoxazole TMP 15-20 mg/kg/day x 21 days; add Prednisolone 40 mg BD if PaO2 < 70 mmHg"]','A','LDH typically elevated in PCP. CD4 usually < 200. Induced sputum or BAL with GMS/silver stain confirms. Initiate/continue ART but may delay if severe (IRIS risk when CD4 very low). KL-6 elevated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','hard','flashcard','What are the unique epidemiological and lab features of Legionella pneumophila?','["Waterborne; outbreaks from cooling towers/hot tubs; causes hyponatraemia, elevated LDH/ALT, diarrhoea; NOT seen on Gram stain; requires BCYE agar; urinary antigen detects serogroup 1"]','A','Legionella does not Gram stain well due to its unusual cell wall. BCYE agar (with charcoal yeast extract) required for culture. Urinary antigen sensitivity ~75%, specificity ~99% for serogroup 1. Treat: Azithromycin or Levofloxacin x 7-14 days.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','easy','flashcard','What is the first-line treatment for typhoid fever per Ghana STG 2017?','["Ciprofloxacin oral 500 mg 12-hourly x 10-14 days; IV Ciprofloxacin 400 mg 8-12-hourly if severe; 2nd line: IV Ceftriaxone 2-4 g daily x 7-10 days"]','A','Ghana STG Evidence Rating B. Salmonella typhi features: rose spots, relative bradycardia, step-ladder fever pattern. Widal test: O titre >= 1:80, H titre >= 1:160 considered significant. Blood culture first week is gold standard.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','easy','flashcard','What are the clinical features and pathophysiology of cholera?','["Profuse watery rice-water diarrhoea, vomiting, rapid dehydration, muscle cramps; NO fever; Vibrio cholerae enterotoxin activates adenylate cyclase raising cAMP and causing massive Cl-/water secretion"]','A','Cholera toxin B subunit binds GM1 ganglioside; A subunit activates Gs. ORS is the cornerstone of treatment. Doxycycline 300 mg single dose (adults) shortens illness. Notify public health authorities immediately.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','easy','flashcard','How is dehydration assessed and treated in a child with acute diarrhoea per Ghana STG?','["No dehydration: Plan A (ORS at home). Some dehydration: Plan B (75 mL/kg ORS over 4 h in facility). Severe dehydration: Plan C (Ringer''s lactate 100 mL/kg IV)"]','A','Ghana STG Tables 1-1 to 1-3. Zinc 10-20 mg/day x 10-14 days reduces duration and recurrence. Continue breastfeeding. Avoid anti-diarrhoeals in children. ORS composition: Na 75 mmol, K 20 mmol, Cl 65 mmol, citrate 10 mmol, glucose 75 mmol/L.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','medium','flashcard','Distinguish hepatitis A from hepatitis E clinically and epidemiologically.','["Both faecal-oral; Hep A: worldwide, rarely fulminant, mostly self-limiting; Hep E: Asia/Africa/sub-Saharan Africa, high maternal mortality up to 20% in pregnancy, no chronic infection"]','A','No chronic hepatitis A or E. HAV vaccine available. HEV: ribavirin used in immunocompromised chronic HEV. HEV in pregnancy risks fulminant liver failure — avoid pregnancy in endemic areas without precautions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','medium','flashcard','What organisms cause traveller''s diarrhoea and how is it treated?','["ETEC (enterotoxigenic E. coli) most common; also Campylobacter, Shigella, Salmonella, Giardia; treat with oral Azithromycin 1 g stat or Ciprofloxacin 500 mg 12-hourly x 3 days + ORS"]','A','Mild: ORS only. Moderate/severe or dysentery: antibiotics shorten illness by 1-2 days. Bismuth subsalicylate for prevention. Avoid prophylactic antibiotics routinely. Rifaximin approved for non-invasive traveller''s diarrhoea.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','medium','flashcard','What are the complications of typhoid fever?','["Intestinal perforation (commonest surgical emergency, week 3), GI haemorrhage, hepatitis, myocarditis, encephalopathy, osteomyelitis in sickle cell disease, relapse (2-3%), chronic carrier state"]','A','Perforation presents with acute abdomen and peritonism. Managed surgically + broad-spectrum IV antibiotics. Chronic typhoid carrier: organisms in gallbladder > 1 year; treat with Ciprofloxacin x 4 weeks +/- cholecystectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','medium','flashcard','Distinguish the mechanism of diarrhoea in Shigella vs Vibrio cholerae.','["Shigella: invasive — invades colonocytes causing bloody mucoid diarrhoea, fever, tenesmus. Cholera: secretory/toxigenic — no mucosal invasion, profuse watery diarrhoea, no blood or fever"]','A','Shigella: treat with Ciprofloxacin or Azithromycin. STEC (E. coli O157): avoid antibiotics and anti-motility agents (HUS risk). Cholera: ORS alone curative for mild; Doxycycline for adults reduces stool output.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','medium','flashcard','How is Helicobacter pylori eradicated per Ghana STG?','["Triple therapy: Omeprazole 20 mg + Amoxicillin 1 g + Clarithromycin 500 mg — all twice daily for 7-14 days"]','A','Ghana STG Table 1-5. Test for H. pylori: urea breath test (gold standard non-invasive), stool antigen, or biopsy urease test (CLOtest). Avoid clarithromycin if local resistance > 15-20%. 2nd line: bismuth quadruple therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','hard','flashcard','A child develops HUS after bloody diarrhoea. Organism, mechanism, and management?','["STEC E. coli O157:H7; Shiga toxins Stx1/Stx2 inhibit protein synthesis in renal endothelium causing microangiopathic haemolytic anaemia + thrombocytopaenia + AKI (HUS triad); management: supportive, dialysis — NO antibiotics (increase Stx release)"]','A','Antibiotics in STEC infection increase Stx release and HUS risk. Avoid anti-motility agents. HUS is the commonest cause of acute renal failure in children. Plasmapheresis occasionally used. Most recover renal function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','hard','flashcard','What is the Widal test and what are its limitations?','["Agglutination test detecting antibodies against Salmonella typhi O (somatic) and H (flagellar) antigens; titres >= 1:80 (O) and >= 1:160 (H) considered significant; but low specificity and high false-positive rate in endemic areas"]','A','Widal cross-reacts with other Salmonella spp., non-typhoidal fevers, and prior vaccination. In endemic Ghana, baseline titres may already be elevated making interpretation unreliable. Blood culture in first week is the gold standard (sensitivity 80%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','easy','flashcard','What features distinguish lower UTI (cystitis) from upper UTI (pyelonephritis)?','["Lower UTI: dysuria, frequency, urgency, suprapubic pain — NO fever. Upper UTI: fever >= 38°C, rigors, loin/flank pain, costovertebral angle tenderness, nausea/vomiting, systemic illness"]','A','Urosepsis = pyelonephritis + systemic organ dysfunction. Women are 10x more commonly affected due to shorter urethra. E. coli accounts for ~80% of community-acquired UTIs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','easy','flashcard','What is the first-line treatment for uncomplicated acute cystitis per Ghana STG 2017?','["Nitrofurantoin 100 mg 6-hourly for 5-7 days (adults); 2nd line: Trimethoprim-Sulfamethoxazole or Amoxicillin-Clavulanate; obtain MSU C&S before starting treatment"]','A','Ghana STG Evidence Rating A. Nitrofurantoin safe in pregnancy (avoid at term — neonatal haemolysis risk). For cystitis in pregnancy: Cefuroxime 500 mg 12-hourly x 5-7 days. Fluoroquinolones: 2nd-line reserve.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','easy','flashcard','What organisms most commonly cause UTIs?','["E. coli (80%), Staphylococcus saprophyticus (young women), Klebsiella pneumoniae, Proteus mirabilis (urease-producer — struvite stones), Enterococcus, Pseudomonas (catheter-associated)"]','A','Proteus mirabilis produces urease splitting urea to ammonia → alkaline urine → struvite (staghorn) calculi. CAUTI: Pseudomonas, Candida, Enterococcus, MRSA common. Remove catheter as primary intervention.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','medium','flashcard','What defines significant bacteriuria and how is UTI confirmed on urinalysis?','["Significant bacteriuria: >= 10^5 CFU/mL on MSU culture; urinalysis: positive nitrites (Gram-negative bacteria), leucocyte esterase (pyuria > 10 WBC/HPF), haematuria"]','A','Suprapubic aspirate: any growth is significant. Catheter specimen: >= 10^2 CFU/mL. Asymptomatic bacteriuria treated only in pregnancy (reduces pyelonephritis risk) and before urological procedures.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','medium','flashcard','How is pyelonephritis treated in a non-pregnant adult?','["Outpatient mild-moderate: Ciprofloxacin 500 mg 12-hourly x 7-14 days oral; hospitalised/severe: IV Ceftriaxone 1-2 g daily or IV Ciprofloxacin 400 mg 12-hourly x 10-14 days"]','A','Obtain urine C&S before antibiotics. No improvement in 48-72 h: renal imaging (USS/CT) to exclude abscess or obstruction. Renal abscess: percutaneous drainage + prolonged antibiotics. Duration 14 days if IV initiated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','medium','flashcard','What are the risk factors and prevention strategies for recurrent UTI in women?','["Risk factors: sexual intercourse, spermicide use, post-menopausal oestrogen deficiency, anatomical abnormalities; prevention: post-coital voiding, cranberry, low-dose prophylactic Nitrofurantoin or Trimethoprim nightly x 6-12 months"]','A','Recurrent UTI = >= 3 episodes/year or >= 2 in 6 months. Topical oestrogen cream for post-menopausal women restores Lactobacillus flora and reduces recurrence. Patient-initiated self-treatment is an option for reliable patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','medium','flashcard','What is the empiric treatment for urosepsis?','["IV Ceftriaxone 2 g daily OR IV Piperacillin-Tazobactam; if ESBL suspected or prior resistant isolate: IV Meropenem; de-escalate based on urine and blood culture results"]','A','Urosepsis accounts for ~25% of all sepsis. Blood and urine cultures before antibiotics. Source control (relieve obstruction, drain abscess, remove infected stone) is critical. Avoid aminoglycosides in AKI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','medium','flashcard','What special considerations apply to UTI in pregnancy?','["All bacteriuria in pregnancy must be treated (risk of pyelonephritis, preterm labour); first-line: Cefuroxime 500 mg 12-hourly x 5-7 days; avoid Nitrofurantoin at term, fluoroquinolones throughout, TMP in 1st trimester"]','A','Untreated asymptomatic bacteriuria in pregnancy leads to pyelonephritis in 25-35%. Screen with MSU at booking and 28 weeks. Nitrofurantoin safe in 2nd trimester but avoid after 36 weeks (risk of neonatal haemolytic anaemia).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','hard','flashcard','A diabetic patient has pneumaturia and CT shows gas in the bladder wall. Diagnosis and management?','["Emphysematous cystitis — gas-forming organisms (E. coli, Klebsiella) fermenting glucose in diabetics; manage with IV antibiotics (Ceftriaxone or Piperacillin-Tazobactam), glycaemic control, catheter drainage; emphysematous pyelonephritis may require nephrectomy"]','A','Emphysematous pyelonephritis: 40% mortality without nephrectomy; percutaneous drainage may spare kidney. CT is gold standard. Risk factors: DM, urinary obstruction, immunocompromise. Always image kidneys to exclude upper tract involvement.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','hard','flashcard','What defines a complicated UTI and how does management differ from uncomplicated?','["Complicated UTI: structural/functional abnormality, male sex, pregnancy, immunosuppression, catheter, recent instrumentation, or drug-resistant organism; treat for 10-14 days guided by C&S; remove precipitating factor"]','A','Males with UTI = complicated by definition (requires urological investigation for underlying cause). Biofilm on catheters evades antibiotics — change catheter before treating. USS/CT to exclude obstruction in all complicated UTIs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','easy','flashcard','Describe the 3 stages of syphilis and their key features.','["Primary: painless indurated chancre (3-90 days). Secondary: maculopapular rash on palms/soles, condylomata lata, mucous patches, generalised lymphadenopathy (6-8 weeks). Tertiary: gummas, cardiovascular syphilis (aortitis), neurosyphilis (tabes dorsalis, general paresis)"]','A','Latent syphilis: positive serology, no symptoms. VDRL/RPR (non-treponemal): screening, titre tracks treatment response. TPHA/FTA-ABS (treponemal): confirmatory, remain positive for life regardless of treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','easy','flashcard','What is the treatment for primary and secondary syphilis per Ghana STG 2017?','["Benzathine Penicillin G 2.4 MU IM stat (1.2 MU into each buttock); penicillin allergy: Doxycycline 100 mg 12-hourly x 14 days or Tetracycline 500 mg 6-hourly x 14 days"]','A','Ghana STG Section 168. Neurosyphilis: IV Benzylpenicillin 3-4 MU every 4 hours x 10-14 days. Jarisch-Herxheimer reaction (fever, rigors 8-12 h after treatment): manage with paracetamol, not a reason to stop treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','easy','flashcard','How is gonorrhoea treated per Ghana STG syndromic management?','["Ceftriaxone IM 250 mg stat (gonorrhoea) PLUS Doxycycline 100 mg 12-hourly x 7 days or Azithromycin 1 g stat (chlamydia) — treat both simultaneously"]','A','Ghana STG: dual therapy mandatory (30% co-infection rate). Cefixime 400 mg oral is alternative to Ceftriaxone. Fluoroquinolone resistance widespread — avoid ciprofloxacin monotherapy for gonorrhoea. Treat partners.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','medium','flashcard','What is the syndromic management approach for STIs in Ghana STG?','["Treat based on clinical syndrome (urethral discharge, vaginal discharge, genital ulcer, lower abdominal pain) without waiting for lab results — covers the most common causative organisms for that syndrome"]','A','Ghana STG rationale: limited lab access in primary care. Urethral discharge: treat gonorrhoea + chlamydia simultaneously. Risk assessment (Note 16-2) guides whether to include cervicitis treatment in vaginal discharge syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','medium','flashcard','What are the causes of genital ulcer disease and their distinguishing features?','["Syphilis: painless indurated ulcer (chancre). Chancroid (H. ducreyi): painful ragged purulent ulcer + unilateral suppurative bubo. HSV: multiple painful vesicles/ulcers + systemic features. Granuloma inguinale: painless beefy-red ulcer without lymphadenopathy"]','A','Ghana STG syndromic approach for genital ulcer: treat syphilis (Benzathine Penicillin) + chancroid (Azithromycin or Ceftriaxone) simultaneously. Add Aciclovir if herpetic lesions suspected.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','medium','flashcard','How is trichomoniasis diagnosed and treated?','["Frothy yellow-green malodorous vaginal discharge, strawberry cervix, pH > 4.5, motile trophozoites on wet prep; treat: Metronidazole 2 g stat (patient and partner)"]','A','Trichomonas vaginalis is a flagellated protozoan. Male partners often asymptomatic but must be treated to prevent reinfection. Alternative: Metronidazole 400 mg 12-hourly x 7 days. Avoid alcohol with metronidazole.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','medium','flashcard','What is pelvic inflammatory disease (PID) and its long-term complications?','["PID: ascending infection of upper reproductive tract (endometritis, salpingitis) by N. gonorrhoeae, C. trachomatis, anaerobes; complications: tubo-ovarian abscess, ectopic pregnancy, infertility, chronic pelvic pain, Fitz-Hugh-Curtis perihepatitis"]','A','Ghana STG outpatient PID: Cefixime + Doxycycline + Metronidazole x 14 days. Inpatient: Ceftriaxone IM + Doxycycline + Metronidazole x 17 days. Remove IUD 3 days after antibiotics initiated. Treat partners.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','medium','flashcard','What is ophthalmia neonatorum and how is it prevented?','["Purulent neonatal conjunctivitis within 5 days of birth from gonococcal infection during delivery; causes corneal ulceration and blindness; prevention: 1% tetracycline or 0.5% erythromycin eye ointment at birth (Crede prophylaxis)"]','A','Ghana STG covers neonatal STI. Treat gonococcal ophthalmia: Ceftriaxone IM 25-50 mg/kg stat. Chlamydial conjunctivitis presents at 5-14 days; treat with systemic Erythromycin x 14 days. Screen mothers for STIs antenatally.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','hard','flashcard','A pregnant woman has positive VDRL. Management to prevent congenital syphilis?','["Benzathine Penicillin G 2.4 MU IM immediately (penicillin allergy: desensitise — oral alternatives inadequate for fetal treatment); monthly VDRL; treat partner; neonatal evaluation at delivery including serology and clinical assessment"]','A','Congenital syphilis features: saddle nose, Hutchinson teeth, interstitial keratitis, sensorineural deafness, periostitis. Neonatal VDRL may reflect maternal antibodies. Neonatal titres 4x higher than mother suggest active congenital infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','hard','flashcard','What is lymphogranuloma venereum (LGV) and how does it present?','["LGV: Chlamydia trachomatis serovars L1-L3; stages: small painless genital papule then painful inguinal lymphadenopathy (fluctuant bubo) then tertiary anorectal syndrome (proctitis, fistulae, elephantiasis); treat: Doxycycline 100 mg 12-hourly x 21 days"]','A','LGV is endemic in sub-Saharan Africa including Ghana. Distinguish from chancroid (painful ulcer, no bubo fluctuation) and granuloma inguinale. Complement fixation titre >= 1:64 supports LGV diagnosis. Aspirate fluctuant buboes — do not incise.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','easy','flashcard','What are the classic clinical features of bacterial meningitis?','["Fever, severe headache, neck stiffness (meningism), photophobia, phonophobia, altered consciousness; Kernig''s sign, Brudzinski''s sign; petechial/purpuric rash suggests meningococcal disease"]','A','Children < 1 year: bulging fontanelle, poor feeding, high-pitched cry, seizures, neck retraction. Always consider meningitis in any child with seizures and fever. Lumbar puncture confirms diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','easy','flashcard','What are the CSF findings in bacterial vs viral meningitis?','["Bacterial: turbid/cloudy, WBC > 1000 (neutrophils predominant), protein > 1 g/L, glucose < 2.2 mmol/L (CSF:blood glucose < 0.4), organisms on Gram stain/culture. Viral: clear, WBC < 500 (lymphocytes), normal/mildly elevated protein, normal glucose"]','A','TBM: lymphocytic pleocytosis, very high protein, very low glucose, fibrin web on standing, ZN stain positive in only 37%. Cryptococcal: India ink positive, high opening pressure. Culture is always the gold standard.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','easy','flashcard','What is the empiric antibiotic treatment for bacterial meningitis in adults < 50 years per Ghana STG?','["Ceftriaxone IV 2-4 g daily PLUS Vancomycin IV 15 mg/kg 12-hourly for 7-14 days; start Dexamethasone 0.15 mg/kg 6-hourly x 4 days ideally before or with first antibiotic dose"]','A','Ghana STG Table 18-13. Cover Meningococcus, Pneumococcus, H. influenzae. Age > 50/immunocompromised: ADD Ampicillin for Listeria. Alternative 1st line: Benzylpenicillin + Chloramphenicol. Alternative 2nd line: Cefotaxime + Vancomycin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','medium','flashcard','What is the role of dexamethasone in bacterial meningitis?','["Reduces inflammation, cerebral oedema and cytokine release; decreases mortality and neurological complications (especially deafness) in pneumococcal and H. influenzae meningitis; 0.15 mg/kg 6-hourly x 4 days, started with or before first antibiotic"]','A','Ghana STG Note 18-19: dexamethasone recommended. Most benefit in pneumococcal meningitis (NNT ~8 to prevent one death). Dexamethasone may reduce CSF vancomycin penetration — consider stopping if not pneumococcal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','medium','flashcard','Which organisms cause bacterial meningitis by age group?','["Neonates: GBS, E. coli, Listeria. Infants/children: S. pneumoniae, N. meningitidis, H. influenzae b. Adults < 50: N. meningitidis, S. pneumoniae. > 50/immunocompromised: Pneumococcus, Listeria, Gram-negatives"]','A','Post-neurosurgery/CSF shunt: Staph. aureus, Gram-negatives, Pseudomonas. HIV (CD4 < 100): Cryptococcus neoformans — India ink stain positive, high opening pressure, cryptococcal antigen (CrAg) test.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','medium','flashcard','What are the features and treatment of herpes simplex encephalitis (HSE)?','["Fever, headache, focal neurological deficits (temporal lobe — aphasia, personality change, olfactory hallucinations), seizures, confusion; MRI: temporal lobe T2 signal; EEG: PLEDs; treat: IV Aciclovir 10 mg/kg 8-hourly x 14-21 days"]','A','HSV-1 most common cause in adults. CSF PCR for HSV is the gold standard (sensitivity 98%). Untreated HSE mortality > 70%. Start Aciclovir empirically immediately — do not await PCR result.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','medium','flashcard','When is lumbar puncture contraindicated in suspected meningitis?','["Papilloedema, focal neurological signs, altered consciousness (GCS < 13), recent seizures, immunocompromise, coagulopathy, or infection over LP site — perform CT head first to exclude mass lesion/raised ICP"]','A','Never delay antibiotics for CT or LP in clinical urgency. Ghana STG: LP only after excluding raised ICP. If CT unavailable and LP contraindicated, treat empirically. Normal CT does not fully exclude raised ICP.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','medium','flashcard','What prophylaxis is given to meningococcal meningitis contacts per Ghana STG?','["Ciprofloxacin 500 mg oral stat (adults); 250 mg for children 5-12 years; alternative: Ceftriaxone IM 250 mg stat (adults) or 125 mg (< 12 years); give within 24 hours to close contacts"]','A','Ghana STG prophylaxis section. Rifampicin 600 mg 12-hourly x 2 days is an alternative (not in pregnancy). Healthcare workers: prophylaxis only if unprotected mouth-to-mouth contact or airway procedure without PPE.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','hard','flashcard','An HIV+ patient (CD4 50) has 2-week headache and confusion. CSF: India ink positive, CrAg titre 1:512. Treatment?','["Cryptococcal meningitis: Induction: Amphotericin B deoxycholate 0.7-1 mg/kg IV daily + Flucytosine 25 mg/kg 6-hourly x 14 days; Consolidation: Fluconazole 400 mg daily x 8 weeks; Maintenance: Fluconazole 200 mg daily until CD4 > 200 x 6 months on ART"]','A','Delay ART 4-5 weeks after cryptococcal treatment to reduce IRIS risk. Serial therapeutic LPs to manage raised ICP (target opening pressure < 20 cmH2O). Monitor Flucytosine: bone marrow toxicity, renal clearance. Liposomal AmB less nephrotoxic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','hard','flashcard','A child has non-blanching petechial/purpuric rash and meningism. Immediate management?','["Immediate IM/IV Benzylpenicillin or Ceftriaxone before transfer; definitive: IV Ceftriaxone 2 g (adult) or 50-80 mg/kg (child) x 7 days; septic shock management (fluids, vasopressors); DIC management; ICU admission"]','A','Neisseria meningitidis serogroups A, C, W135, Y covered by MenACWY vaccine. Waterhouse-Friderichsen: bilateral adrenal haemorrhage + shock + DIC — high mortality; may need hydrocortisone. Non-blanching rash = emergency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','easy','flashcard','What organisms commonly cause cellulitis and what is the first-line treatment per Ghana STG?','["Group A Streptococcus (S. pyogenes) and Staphylococcus aureus; outpatient first-line: Amoxicillin 500 mg-1 g 8-hourly PLUS Flucloxacillin 500 mg 6-hourly oral x 7 days"]','A','Ghana STG Chapter 23 Cellulitis. Penicillin allergy: Erythromycin or Clindamycin. Inpatient: IV Amoxicillin-Clavulanate + IV Cloxacillin; step down when improving. Mark advancing border with pen. Elevate limb.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','easy','flashcard','What distinguishes erysipelas from cellulitis?','["Erysipelas: superficial dermis + lymphatics, sharply demarcated raised border, facial or lower leg, caused by S. pyogenes. Cellulitis: deeper dermis/subcutaneous tissue, poorly demarcated border, S. aureus also implicated"]','A','Erysipelas historically treated with Benzylpenicillin (pure streptococcal). Cellulitis needs broader coverage including Staphylococcus. Both: rule out DVT, deep abscess, and necrotising fasciitis before outpatient management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','easy','flashcard','What is impetigo and how is it treated?','["Superficial skin infection; non-bullous (honey-coloured crusted lesions — Strep/Staph) or bullous (fluid-filled blisters — Staph aureus exfoliatin toxin); treat: topical Mupirocin 3x/day or oral Flucloxacillin x 5-7 days"]','A','Spread by direct contact. Post-streptococcal glomerulonephritis can follow non-bullous impetigo (antibiotics prevent spread but may not prevent GN). Bullous impetigo and spreading infection require systemic antibiotics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','medium','flashcard','What clinical clues distinguish necrotising fasciitis from cellulitis?','["Severe disproportionate pain then paradoxical anaesthesia; rapid spread despite antibiotics; woody hard consistency; skin necrosis/bullae; crepitus (gas); haemodynamic instability; finger test: no resistance to blunt dissection in fascia plane"]','A','LRINEC score >= 6 (CRP > 150, WBC > 25, Hb < 13.5, Na < 135, creatinine > 141, glucose > 10) = high risk for NF. CT: fascial air/thickening confirms. Surgical exploration is diagnostic and therapeutic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','medium','flashcard','How is necrotising fasciitis managed?','["Emergency surgical debridement (fasciotomy/necrosectomy) is life-saving; IV antibiotics: Meropenem or Piperacillin-Tazobactam + Clindamycin (inhibits toxin production) + Vancomycin for MRSA; ICU; IVIG for streptococcal toxic shock"]','A','Type 1: polymicrobial (DM, immunosuppression). Type 2: Group A Strep or MRSA (healthy adults). Mortality 20-40%; higher with surgical delay > 24 h. Hyperbaric oxygen is adjunct where available.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','medium','flashcard','What are the indications for admission and IV antibiotics in cellulitis?','["Failed outpatient treatment; rapidly spreading infection despite 48-72 h oral antibiotics; systemic sepsis; facial/orbital cellulitis; lymphoedema; immunocompromise; Fournier''s gangrene"]','A','Ghana STG: inpatient cellulitis — IV Amoxicillin-Clavulanate + IV Cloxacillin, step down to oral on improvement. Fournier''s gangrene (scrotal/perineal NF): urological emergency — immediate debridement + broad-spectrum IV antibiotics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','medium','flashcard','What is MRSA and how does it affect SSTI management?','["MRSA: Methicillin-Resistant Staphylococcus aureus resistant to all beta-lactams (mecA gene encoding PBP2a); hospital-acquired: Vancomycin IV; community-acquired MRSA (CA-MRSA): Trimethoprim-Sulfamethoxazole oral or Clindamycin"]','A','CA-MRSA (USA300): causes furunculosis and abscesses in healthy individuals. Linezolid, Daptomycin, Tigecycline are alternatives. Decolonise carriers: intranasal Mupirocin + chlorhexidine body washes. Screen ICU admissions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','medium','flashcard','How is a post-surgical wound infection managed?','["Open wound and remove sutures, drain pus, wound swab C&S, irrigate with saline, debride necrotic tissue, pack open wound; systemic Amoxicillin-Clavulanate if cellulitis/systemic signs; ensure tetanus prophylaxis"]','A','Ghana STG: for Fournier''s/necrotising scrotal infections: Gentamicin + Ampicillin + Metronidazole IV. Most simple wound infections managed by drainage alone without systemic antibiotics. Monitor for dehiscence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','hard','flashcard','A diabetic patient has a foul-smelling foot ulcer with gas on X-ray. Organisms and management?','["Diabetic foot: polymicrobial — S. aureus, Streptococcus, Gram-negatives (E. coli, Klebsiella, Proteus), anaerobes (Bacteroides, Clostridium); manage: glycaemic control, surgical debridement, IV Piperacillin-Tazobactam + Metronidazole, vascular assessment"]','A','Wagner grading 0-5 for diabetic foot ulcers. Osteomyelitis: MRI gold standard; bone biopsy for definitive culture guides prolonged antibiotic therapy. Clostridium perfringens gas gangrene: penicillin + clindamycin + emergency surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','hard','flashcard','What is Buruli ulcer (common in Ghana) and how is it treated?','["Caused by Mycobacterium ulcerans producing mycolactone toxin; painless subcutaneous nodule progressing to extensive ulcer with undermined edges; treat: Rifampicin 10 mg/kg + Streptomycin 15 mg/kg IM daily x 8 weeks, OR Rifampicin + Clarithromycin"]','A','Ghana is one of the world''s highest-burden countries for Buruli ulcer. PCR on swab confirms diagnosis. Wound care and physiotherapy prevent disability. Surgery for large lesions or complications. Notify National Buruli Ulcer Control Programme.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','easy','flashcard','What is the mechanism of action of beta-lactam antibiotics?','["Inhibit bacterial cell wall synthesis by binding Penicillin-Binding Proteins (PBPs) and blocking transpeptidation of peptidoglycan cross-linking, causing osmotic lysis; bactericidal"]','A','Beta-lactam ring is the pharmacophore. Includes penicillins, cephalosporins, carbapenems, monobactams. Time-dependent killing — efficacy depends on time drug concentration stays above MIC. Beta-lactamase enzymes destroy the beta-lactam ring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','easy','flashcard','What is the mechanism of action of aminoglycosides?','["Bind to 30S ribosomal subunit causing misreading of mRNA and incorporation of wrong amino acids; aberrant proteins damage the cell membrane; concentration-dependent bactericidal killing"]','A','Examples: Gentamicin, Amikacin, Streptomycin, Tobramycin. Concentration-dependent: once-daily dosing maximises efficacy and reduces nephrotoxicity. Ototoxic (irreversible) and nephrotoxic — monitor trough levels. Avoid in AKI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','easy','flashcard','What is the mechanism of action of fluoroquinolones?','["Inhibit DNA gyrase (topoisomerase II) and topoisomerase IV causing DNA strand breaks and bacterial cell death; broad-spectrum bactericidal; concentration-dependent killing"]','A','Examples: Ciprofloxacin (Gram-negative dominant), Levofloxacin and Moxifloxacin (respiratory tract). Avoid in pregnancy, children (arthropathy risk), tendinitis. Prolongs QTc interval. Resistance via gyrase mutations, efflux pumps.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','medium','flashcard','Name the 4 main mechanisms of antibiotic resistance.','["1. Enzymatic inactivation (beta-lactamase destroys ring). 2. Target modification (PBP2a in MRSA; 23S rRNA changes for macrolides). 3. Efflux pumps (expel drug — tetracyclines). 4. Reduced permeability (porin loss — Pseudomonas, carbapenem resistance)"]','A','Horizontal gene transfer via plasmids, transposons, and integrons spreads resistance genes between bacteria rapidly. ESKAPE pathogens (Enterococcus, S. aureus, Klebsiella, Acinetobacter, Pseudomonas, Enterobacter) are priority resistant organisms per WHO.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','medium','flashcard','What is the mechanism of action of macrolides and their key clinical uses?','["Bind to 23S rRNA of 50S ribosomal subunit blocking peptidyl transferase activity; bacteriostatic; cover Gram-positives, atypicals (Mycoplasma, Chlamydia, Legionella), H. pylori eradication, Campylobacter"]','A','Azithromycin: long tissue half-life (68 h) enables once-daily dosing and short courses. Clarithromycin: best for H. pylori and MAC. Erythromycin: significant GI side effects (motilin receptor). Resistance: erm genes (methylation) or mef genes (efflux).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','medium','flashcard','What are the key principles of antimicrobial stewardship (ASP)?','["Right drug, right dose, right route, right duration; obtain cultures before antibiotics; de-escalate based on results; use narrowest spectrum effective agent; 48-72 h review; avoid unnecessary antibiotics; educate prescribers"]','A','ASP reduces C. difficile rates, antimicrobial resistance, adverse effects, and costs. Core strategies: prospective audit with feedback, formulary restriction, prior authorisation, clinical guidelines. Ghana STG embeds stewardship through evidence-based first-line recommendations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','medium','flashcard','What are the mechanism of action of tetracyclines and their key uses?','["Bind to 30S ribosomal subunit preventing aminoacyl-tRNA binding; bacteriostatic; cover Gram-positives, Gram-negatives, atypicals, rickettsiae, Chlamydia, Brucella, malaria prevention (doxycycline)"]','A','Doxycycline: preferred (better bioavailability, longer half-life, once or twice daily). Avoid in children < 8 years (dental staining, bone deposition) and pregnancy. Photosensitivity common. Resistance: tet efflux genes or ribosomal protection proteins.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','medium','flashcard','What is the mechanism and treatment of Clostridioides difficile colitis?','["C. difficile releases toxins A (enterotoxin) and B (cytotoxin) after broad-spectrum antibiotic disruption of gut flora causing pseudomembranous colitis; treat: stop precipitating antibiotic; Vancomycin oral 125 mg 6-hourly x 10 days (preferred); Fidaxomicin 200 mg 12-hourly x 10 days for recurrence"]','A','Precipitated by clindamycin, cephalosporins, fluoroquinolones. Diagnosis: stool NAAT or toxin EIA. Recurrent C. diff: faecal microbiota transplant (FMT) ~90% effective. Avoid anti-motility agents. Isolation and contact precautions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','hard','flashcard','Explain MIC, time-dependent vs concentration-dependent killing, and post-antibiotic effect (PAE).','["MIC: minimum inhibitory concentration inhibiting visible growth. Time-dependent (beta-lactams): efficacy depends on time above MIC — give more frequent doses or continuous infusion. Concentration-dependent (aminoglycosides, fluoroquinolones): efficacy depends on Cmax/MIC ratio — give larger less-frequent doses. PAE: persistent growth suppression after drug removal — long PAE in aminoglycosides/fluoroquinolones allows once-daily dosing"]','A','AUC/MIC ratio predicts fluoroquinolone efficacy. Vancomycin target: AUC/MIC >= 400 mg·h/L. PK/PD principles guide dose optimisation and reduce resistance emergence during treatment. Monte Carlo simulations inform dosing regimens.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','hard','flashcard','What are ESBL-producing organisms and how do they affect antibiotic choice?','["Extended-Spectrum Beta-Lactamase (ESBL) producers (E. coli, Klebsiella) hydrolyse most penicillins and cephalosporins including 3rd/4th generation; carbapenems (Meropenem, Ertapenem) are treatment of choice for severe infections"]','A','ESBL genes are plasmid-mediated — spread rapidly. Risk: prior antibiotics, hospital/nursing home, indwelling devices, international travel. Carbapenem-resistant Enterobacteriaceae (CRE) with NDM/KPC: last-resort agents — Ceftazidime-avibactam, Colistin, Polymyxin B. Report to infection control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
